const payload = $input.first().json.body;

const config = payload.configuracaoAgente || {};
const nomeAgente = config.nome_agente || 'Assistente';
const tom = config.tom || 'profissional';

const objetivos = [];
if (config.objetivo_vendas) objetivos.push('vendas');
if (config.objetivo_atendimento) objetivos.push('atendimento');
if (config.objetivo_suporte) objetivos.push('suporte');

const baseConhecimento = (payload.baseConhecimento || [])
  .map((trecho, i) => `[${i + 1}] ${trecho}`)
  .join('\n\n');

const nomesAutor = { cliente: 'Cliente', ia: nomeAgente, atendente: 'Atendente', sistema: 'Sistema' };
const historico = (payload.historico || [])
  .map((m) => `${nomesAutor[m.autor] || m.autor}: ${m.texto}`)
  .join('\n');

const promptSistema = `Você é ${nomeAgente}, o assistente de atendimento via WhatsApp de uma empresa. Tom de voz: ${tom}. Seus objetivos: ${objetivos.join(', ') || 'atendimento geral'}.

Regras de transferência para humano: ${config.regras_transferencia || 'transfira quando o cliente pedir explicitamente ou quando você não tiver certeza da resposta.'}
Regras para abrir chamado: ${config.regras_abertura_chamado || 'abra um chamado quando identificar um problema que precisa de acompanhamento humano (ex.: atraso, erro, reclamação).'}
Limites de atuação: ${config.limites_atuacao || 'não prometa prazos ou valores que não estejam no contexto abaixo.'}

Trechos relevantes da base de conhecimento da empresa:
${baseConhecimento || '(nenhum trecho relevante encontrado)'}

Histórico recente da conversa:
${historico || '(sem histórico)'}

Responda SOMENTE em JSON válido, sem markdown, no formato exato:
{"acao": "responder" | "transferir" | "abrir_chamado", "resposta": "texto a enviar ao cliente pelo WhatsApp (ou null se acao = transferir sem mensagem de handoff)", "chamado": {"problema": "...", "descricao": "...", "prioridade": "baixa" | "media" | "alta"} ou null}`;

return [{
  json: {
    empresaId: payload.empresaId,
    conversaId: payload.conversaId,
    promptSistema,
    mensagemAtual: payload.mensagemAtual,
  },
}];

const resposta = $input.first().json;
const conteudo = resposta.choices && resposta.choices[0] && resposta.choices[0].message
  ? resposta.choices[0].message.content
  : null;

let decisao;
try {
  decisao = JSON.parse(conteudo);
} catch (err) {
  // Se a IA não devolveu um JSON válido, joga pra fila de humanos em vez
  // de arriscar mandar algo quebrado pro cliente.
  decisao = { acao: 'transferir', resposta: null, chamado: null };
}

const acoesValidas = ['responder', 'transferir', 'abrir_chamado'];
if (!acoesValidas.includes(decisao.acao)) {
  decisao.acao = 'transferir';
}

return [{ json: decisao }];
